INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (11, 21, 'theory', 'Квиз: CSS — адаптивность, состояния и анимации');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 21, 0, 'Что даёт мета-тег viewport со значением width=device-width?', '["Он отключает масштабирование страницы пальцами","Он задаёт максимальную ширину всех изображений","Он говорит мобильному браузеру взять ширину окна, равную ширине экрана устройства, и не притворяться десктопом","Он включает тёмную тему на телефонах"]', 2, 'Без этого мета-тега телефон считает окно шириной около тысячи пикселей и уменьшает страницу целиком, а медиа-запросы по ширине работают неверно. С width=device-width ширина вьюпорта равна реальной ширине экрана.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 21, 1, 'Что означает подход «сначала мобильная версия» в CSS?', '["Базовые правила пишут для узкого экрана, а для широких добавляют @media (min-width: …)","Для телефона создают отдельный сайт на другом адресе","Все правила пишут для десктопа, а потом отключают их запросами с max-width","Страницу проверяют только на телефоне"]', 0, 'Телефон получает базовый, самый лёгкий набор стилей, а расширение вёрстки добавляется по мере роста окна через min-width. Так не нужно переопределять и отменять лишнее.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 21, 2, 'Чем контейнерный запрос (@container) отличается от медиа-запроса?', '["Он работает только в печатной версии страницы","Он реагирует на цвет фона родителя","Он заменяет мета-тег viewport","Он смотрит на размер ближайшего родителя-контейнера (container-type), а не на размер окна"]', 3, 'Родителю задают container-type, и правило @container срабатывает по его размеру. Поэтому один и тот же компонент по-разному выглядит в широкой колонке и в узкой боковой панели независимо от ширины окна.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 21, 3, 'Почему для анимации советуют transform и opacity, а не left или width?', '["Потому что left и width нельзя использовать в transition","Они выполняются на этапе композиции, без пересчёта раскладки и перерисовки, и не дёргают остальную страницу","Потому что они работают без указания длительности","Потому что их понимают все браузеры, а остальные свойства — только некоторые"]', 1, 'Изменение left или width заставляет браузер пересчитывать раскладку и перерисовывать соседей. Transform и opacity меняют лишь то, как слой композитится на видеокарте, поэтому анимация остаётся плавной даже на слабых телефонах.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 21, 4, 'Для чего нужен запрос @media (prefers-reduced-motion: reduce)?', '["Чтобы уменьшить размер файлов анимации","Чтобы замедлить любые переходы в два раза","Чтобы отключить или смягчить движение у тех, кто включил в системе настройку «уменьшить движение»","Чтобы определить слабое устройство и снизить частоту кадров"]', 2, 'Настройка нужна людям, которых тошнит от параллакса и вращений, а также при риске приступов. Браузер передаёт её странице, а в этом запросе анимацию отключают или заменяют мягким появлением.');
